package app.noir.mobile;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.widget.RemoteViews;
import org.json.*;
import java.util.*;

public final class NextUpWidget extends AppWidgetProvider {
 static final String CHECK="app.noir.mobile.NEXT_UP_CHECK";static final java.util.concurrent.atomic.AtomicBoolean RUNNING=new java.util.concurrent.atomic.AtomicBoolean(),DIRTY=new java.util.concurrent.atomic.AtomicBoolean();
 @Override public void onUpdate(Context c,AppWidgetManager manager,int[] ids){updateAll(c);}
 @Override public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(!CHECK.equals(intent.getAction()))return;String id=intent.getStringExtra("item"),profile=intent.getStringExtra("profile");if(id==null||id.isEmpty()||profile==null||profile.isEmpty())return;PendingResult pending=goAsync();new Thread(()->{try{DataStore data=NoirApp.dataFor(c,profile);JSONObject item=data.item(id);if(item!=null&&!DataStore.watched(item)){data.mark(id,true,System.currentTimeMillis(),false);data.syncSoon();}updateAll(c);}finally{pending.finish();}},"Noir-widget-check").start();}
 public static void updateAll(Context context){DIRTY.set(true);if(!RUNNING.compareAndSet(false,true))return;Context c=context.getApplicationContext();AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,NextUpWidget.class));if(ids.length==0){DIRTY.set(false);RUNNING.set(false);return;}new Thread(()->{try{do{DIRTY.set(false);DataStore data=NoirApp.data;boolean owned=data==null;if(owned)data=new DataStore(c);JSONObject next=next(data);for(int widget:ids){RemoteViews views=new RemoteViews(c.getPackageName(),R.layout.next_up_widget);Intent open=new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);views.setOnClickPendingIntent(R.id.next_up_root,PendingIntent.getActivity(c,widget,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));views.setTextViewText(R.id.next_up_brand,Loc.t("NOIR · UP NEXT"));views.setTextViewText(R.id.next_up_streak,Loc.f("Day %d streak",PhoneRewardCard.stats(data).streak));views.setImageViewResource(R.id.next_up_poster,android.R.drawable.ic_media_play);views.setTextViewText(R.id.next_up_check,"✓");views.setContentDescription(R.id.next_up_check,Loc.t("Mark watched"));views.setViewVisibility(R.id.next_up_check,next==null?android.view.View.GONE:android.view.View.VISIBLE);if(next==null){views.setTextViewText(R.id.next_up_title,Loc.t("All caught up"));views.setTextViewText(R.id.next_up_episode,Loc.t("Open Noir to find your next story"));}else{views.setTextViewText(R.id.next_up_title,next.optString("title"));views.setTextViewText(R.id.next_up_episode,PhoneSmart.label(next)+(next.optString("episodeTitle").isEmpty()?"":" · "+next.optString("episodeTitle")));Intent check=new Intent(c,NextUpWidget.class).setAction(CHECK).putExtra("item",next.optString("id")).putExtra("profile",data.profileId).setData(android.net.Uri.parse("noir-widget://check/"+widget+"/"+android.net.Uri.encode(data.profileId)+"/"+android.net.Uri.encode(next.optString("id"))));views.setOnClickPendingIntent(R.id.next_up_check,PendingIntent.getBroadcast(c,widget,check,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));java.io.File file=data.art(next.optString("poster"));if(file.exists()){BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),o);o.inSampleSize=Math.max(1,o.outWidth/160);o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(file.getPath(),o);if(b!=null)views.setImageViewBitmap(R.id.next_up_poster,b);}}manager.updateAppWidget(widget,views);}if(owned){data.network.shutdown();data.images.shutdown();}}while(DIRTY.get());}finally{RUNNING.set(false);if(DIRTY.get())updateAll(c);}},"Noir-widget").start();}
 static long air(JSONObject i){long value=DataStore.date(i.optString("airsAt"));if(value==0)try{value=java.time.LocalDate.parse(i.optString("airsAt").substring(0,10)).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();}catch(Exception ignored){}return value;}
 static JSONObject next(DataStore data){Map<String,List<JSONObject>> groups=new HashMap<>();for(JSONObject i:DataStore.objects(data.itemsShared()))if(!i.optBoolean("movie")&&i.optInt("season")>0&&i.optInt("episode")>0&&!i.optString("status").equals("Dropped"))groups.computeIfAbsent(i.optString("group"),k->new ArrayList<>()).add(i);JSONObject best=null;long bestAt=-1;for(List<JSONObject> group:groups.values()){long recent=0;int furthest=-1;JSONObject candidate=null;group.sort(Comparator.comparingInt((JSONObject i)->i.optInt("season")).thenComparingInt(i->i.optInt("episode")));for(int n=0;n<group.size();n++){JSONObject i=group.get(n);if(DataStore.watched(i)){furthest=n;for(JSONObject v:DataStore.objects(i.optJSONArray("viewings")))recent=Math.max(recent,DataStore.date(v.optString("watchedAt")));}}if(furthest<0)continue;for(int n=furthest+1;n<group.size()&&candidate==null;n++){JSONObject i=group.get(n);if(!DataStore.watched(i)&&air(i)<=System.currentTimeMillis())candidate=i;}if(candidate==null)for(JSONObject i:group)if(!DataStore.watched(i)&&air(i)<=System.currentTimeMillis()){candidate=i;break;}if(candidate!=null&&recent>bestAt){best=candidate;bestAt=recent;}}return best;}
}
